// Page layer — generated by line-matcher from the design. Props in, JSX out; no business logic.
import OrgsItemRow from "../component/OrgsItemRow.jsx";

export default function OrgsItemsPage({
  status,
  error,
  itemCount,
  qtyTotal,
  rows,
  selectedId,
  formValues,
  onEdit,
  onDelete,
  onSave,
  onCancel,
}) {
  return (
    <main className="page">
      {status === "loading" && <p className="status">Loading…</p>}
      {error && (
        <p role="alert" className="error">
          {error}
        </p>
      )}
      <header className="header">
        <h1>Items</h1>
        <p className="meta">
          <span>{itemCount}</span>
          {" items · total qty "}
          <span>{qtyTotal}</span>
        </p>
      </header>

      <form
        className="card form"
        key={selectedId ?? "new"}
        onSubmit={(e) => {
          e.preventDefault();
          onSave(Object.fromEntries(new FormData(e.currentTarget)));
        }}
      >
        <input name="name" placeholder="Name" required defaultValue={formValues.name ?? ""} />
        <input name="sku" placeholder="SKU" required defaultValue={formValues.sku ?? ""} />
        <input
          name="qty"
          type="number"
          placeholder="Qty"
          required
          defaultValue={formValues.qty ?? ""}
        />
        <button type="submit" className="primary">
          Save
        </button>
        <button type="button" onClick={onCancel}>
          Cancel
        </button>
      </form>

      <table className="card table">
        <thead>
          <tr>
            <th>Item</th>
            <th>SKU</th>
            <th>Qty</th>
            <th></th>
          </tr>
        </thead>
        <tbody>
          {rows.map((row) => (
            <OrgsItemRow
              key={row.id}
              row={row}
              selected={row.id === selectedId}
              onEdit={onEdit}
              onDelete={onDelete}
            />
          ))}
        </tbody>
      </table>
    </main>
  );
}
